\section*{Claim}
Validity-preserving constraint augmentation is the correct abstraction for high-value bootstrap refinements. Let $F$ and $F^+$ be feasible sets for the same plaquette coordinate $x_P$, with
\[
F^+\subseteq F,
\qquad X^\ast\in F^+,
\qquad x_P(X^\ast)=p.
\]
Define
\[
L:=\inf_{X\in F}x_P(X),\quad U:=\sup_{X\in F}x_P(X),
\qquad
L^+:=\inf_{X\in F^+}x_P(X),\quad U^+:=\sup_{X\in F^+}x_P(X).
\]
Then
\[
L\leq L^+\leq p\leq U^+\leq U.
\]
Thus any additional exact positivity matrix, exact loop equation, exact trace identity, or closed path-family restriction that only removes spurious assignments cannot hurt validity and can only tighten the certified interval.

\section*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & F^+\subseteq F.\\[0.4em]
\text{(P2)} & X^\ast\in F^+\text{ and }x_P(X^\ast)=p.\\[0.4em]
\text{(P3)} & L,L^+,U,U^+\text{ are the infima and suprema displayed in the claim.}\\[0.4em]
\text{(P4)} & \text{The plaquette-bound goal prefers validity first and then smaller interval width.}
\end{array}
\]

\section*{Derivation}
Since $F^+\subseteq F$, every lower bound over $F$ is no larger than the lower bound over the smaller set:
\begin{align}
L=\inf_{X\in F}x_P(X)\leq \inf_{X\in F^+}x_P(X)=L^+.
\end{align}
Since $X^\ast\in F^+$,
\begin{align}
L^+=\inf_{X\in F^+}x_P(X)\leq x_P(X^\ast)=p.
\end{align}
The same inclusion reverses the supremum inequality:
\begin{align}
U^+=\sup_{X\in F^+}x_P(X)\leq \sup_{X\in F}x_P(X)=U.
\end{align}
Again using $X^\ast\in F^+$,
\begin{align}
p=x_P(X^\ast)\leq \sup_{X\in F^+}x_P(X)=U^+.
\end{align}
The four inequalities yield the chain. Moreover,
\begin{align}
U^+-L^+\leq U-L,
\end{align}
so, after validity is preserved, the augmented feasible set is weakly preferred by the width component of the plaquette-bound objective.

\section*{Final Result}
\[
\boxed{F^+\subseteq F\text{ and }X^\ast\in F^+\Longrightarrow L\leq L^+\leq p\leq U^+\leq U}
\]
\hfill$\blacksquare$

